// Projection Transitions — Geo, route: jsx
// Source: projection-transitions
//
// Self-contained: every local import is inlined below. Requires only d3, d3-geo-projection, geojson, react, topojson-client, topojson-specification, us-atlas, world-atlas.
// d3-geo-projection ships no types — keep untyped-modules.d.ts beside this file.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

/// <reference path="./untyped-modules.d.ts" />

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString } from 'geojson';
import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';
import { geoAitoffRaw, geoBoggsRaw, geoEckert4Raw, geoHammerRaw, geoKavrayskiy7Raw, geoMollweideRaw, geoNaturalEarth2Raw, geoRobinsonRaw, geoSinusoidalRaw, geoWinkel3Raw } from 'd3-geo-projection';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

const MARGIN = { top: 10, right: 10, bottom: 34, left: 10 };
const FRAME_MS = 40;
const MORPH_FRAMES = 30;
const HOLD_FRAMES = 18;
const CYCLE = MORPH_FRAMES + HOLD_FRAMES;

const sphere: d3.GeoSphere = { type: 'Sphere' };
const graticule = d3.geoGraticule().step([20, 20])();

/** Equirectangular's raw projection is the identity on radians. */
const equirectangularRaw: d3.GeoRawProjection = (x, y) => [x, y];

// Every projection here is well defined over the whole sphere, which is what makes a
// point-by-point interpolation between any two of them stay finite.
const TOUR: { name: string; raw: d3.GeoRawProjection }[] = [
  { name: 'Equirectangular', raw: equirectangularRaw },
  { name: 'Mollweide', raw: geoMollweideRaw },
  { name: 'Winkel tripel', raw: geoWinkel3Raw },
  { name: 'Robinson', raw: geoRobinsonRaw },
  { name: 'Eckert IV', raw: geoEckert4Raw },
  { name: 'Aitoff', raw: geoAitoffRaw },
  { name: 'Hammer', raw: geoHammerRaw(2) },
  { name: 'Kavrayskiy VII', raw: geoKavrayskiy7Raw },
  { name: "Boggs' eumorphic", raw: geoBoggsRaw },
  { name: 'Sinusoidal', raw: geoSinusoidalRaw },
  { name: 'Natural Earth II', raw: geoNaturalEarth2Raw },
];

const lerp1 = (a: number, b: number, t: number) => (1 - t) * a + t * b;

const lerp2 = (a: [number, number], b: [number, number], t: number): [number, number] => [
  lerp1(a[0], b[0], t),
  lerp1(a[1], b[1], t),
];

export default function ProjectionTransitions({ width }: { width: number }) {
  const innerWidth = Math.max(1, width - MARGIN.left - MARGIN.right);
  const innerHeight = Math.max(1, Math.round(innerWidth * 0.5));
  const height = innerHeight + MARGIN.top + MARGIN.bottom;
  const [frame, setFrame] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => setFrame((f) => (f + 1) % (CYCLE * TOUR.length)), FRAME_MS);
    return () => clearInterval(timer);
  }, []);

  // Each projection carries the scale and translate that fit the sphere to the frame, so
  // the morph interpolates the fitted views rather than the raw unit-square outputs.
  const fitted = useMemo(
    () =>
      TOUR.map(({ name, raw }) => {
        const p = d3
          .geoProjection(raw)
          .fitExtent(
            [
              [0.5, 0.5],
              [innerWidth - 0.5, innerHeight - 0.5],
            ],
            sphere
          );
        return { name, raw, scale: p.scale(), translate: p.translate() };
      }),
    [innerWidth, innerHeight]
  );

  const from = fitted[Math.floor(frame / CYCLE)];
  const to = fitted[(Math.floor(frame / CYCLE) + 1) % TOUR.length];
  const t = d3.easeCubicInOut(Math.min(1, (frame % CYCLE) / MORPH_FRAMES));

  const shapes = useMemo(() => {
    const projection = d3
      .geoProjection((x, y) => lerp2(from.raw(x, y), to.raw(x, y), t))
      .scale(lerp1(from.scale, to.scale, t))
      .translate(lerp2(from.translate, to.translate, t))
      .precision(0.5);
    const path = d3.geoPath(projection);
    return {
      outline: path(sphere) ?? '',
      grid: path(graticule) ?? '',
      land: path(worldLand) ?? '',
    };
  }, [from, to, t]);

  if (width === 0) return null;

  const label = t < 1 ? `${from.name} → ${to.name}` : to.name;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`World map morphing continuously between eleven whole-earth projections, currently ${label}`}
    >
      <defs>
        <clipPath id="projtrans-outline">
          <path d={shapes.outline} />
        </clipPath>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g clipPath="url(#projtrans-outline)">
          <path d={shapes.grid} fill="none" stroke="var(--line)" strokeWidth={0.5} />
          <path d={shapes.land} fill="var(--accent)" fillOpacity={0.85} />
        </g>
        <path d={shapes.outline} fill="none" stroke="var(--muted)" strokeWidth={0.75} />

        <text
          x={innerWidth / 2}
          y={innerHeight + 18}
          textAnchor="middle"
          fill="var(--text)"
          fontSize={12}
        >
          {label}
        </text>

        {innerWidth > 260 && (
          <g transform={`translate(${innerWidth / 2 - (TOUR.length - 1) * 5},${innerHeight + 28})`}>
            {TOUR.map((p, i) => (
              <circle
                key={p.name}
                cx={i * 10}
                cy={0}
                r={2.5}
                fill={p.name === to.name ? 'var(--accent)' : 'var(--line)'}
              />
            ))}
          </g>
        )}
      </g>
    </svg>
  );
}
